#!/usr/bin/env python3
"""Shared HTTP client for the shipped-orders reconciliation (working file, not a deliverable).

Rules it follows:
  * every non-200 response is logged verbatim (status, headers, body) to events.log
  * 401/403 -> fetch a fresh token and repeat the SAME request
  * 429     -> wait exactly as long as the service says (plus a small margin), repeat the same request
  * 5xx / network errors / unparseable bodies -> repeat the same request with backoff (bounded, then abort loudly)
  * 404     -> returned to the caller as NotFound (a real answer, not a failure)
  * anything it does not recognise -> abort loudly instead of guessing
"""
import email.utils
import json
import re
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
EVENTS = "/tmp/recon/events.log"
WAIT_MARGIN = 0.25          # seconds added on top of whatever the service tells us to wait
MAX_TRANSIENT_RETRIES = 15  # per request, for 5xx / network errors / bad bodies


def log(msg):
    line = "%s %s" % (time.strftime("%H:%M:%S"), msg)
    print(line, flush=True)
    with open(EVENTS, "a") as fh:
        fh.write(line + "\n")


class NotFound(Exception):
    pass


class Abort(Exception):
    pass


def _send(method, path, token=None, timeout=30):
    req = urllib.request.Request(BASE + path, method=method)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            return resp.status, dict(resp.headers), resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as err:
        return err.code, dict(err.headers), err.read().decode("utf-8", "replace")


def _retry_after_seconds(headers, body):
    """Return the wait (seconds) the service asked for, or None if it did not say in a form we know."""
    for k, v in headers.items():
        if k.lower() == "retry-after":
            v = v.strip()
            if re.fullmatch(r"\d+(\.\d+)?", v):
                return float(v)
            try:
                when = email.utils.parsedate_to_datetime(v)
                return max(0.0, when.timestamp() - time.time())
            except Exception:
                pass
    try:
        obj = json.loads(body)
    except Exception:
        return None
    if isinstance(obj, dict):
        for key in ("retry_after", "retry_after_seconds", "retry_after_s", "wait", "wait_seconds", "retry_in"):
            if key in obj and isinstance(obj[key], (int, float)) and not isinstance(obj[key], bool):
                return float(obj[key])
        for key in ("retry_after_ms", "wait_ms"):
            if key in obj and isinstance(obj[key], (int, float)) and not isinstance(obj[key], bool):
                return float(obj[key]) / 1000.0
    return None


class Client:
    def __init__(self):
        self.token = None
        self.stats = {
            "requests": 0, "tokens_issued": 0, "ok": 0, "401_403": 0, "429": 0,
            "5xx": 0, "net_err": 0, "bad_body": 0, "404": 0, "waited_s": 0.0,
        }

    # -- tokens -------------------------------------------------------------
    def refresh_token(self):
        transient = 0
        while True:
            self.stats["requests"] += 1
            try:
                status, headers, body = _send("POST", "/token")
            except Exception as exc:  # network trouble
                self.stats["net_err"] += 1
                transient += 1
                log("POST /token network error: %r (attempt %d)" % (exc, transient))
                if transient > MAX_TRANSIENT_RETRIES:
                    raise Abort("token endpoint unreachable")
                time.sleep(min(2 ** transient, 30))
                continue
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                except Exception:
                    raise Abort("unparseable token response: %r" % body)
                self.token = tok
                self.stats["tokens_issued"] += 1
                self.stats["ok"] += 1
                log("new token issued: %s (token #%d)" % (tok, self.stats["tokens_issued"]))
                return
            log("POST /token -> %s headers=%s body=%r" % (status, headers, body))
            if status == 429:
                self.stats["429"] += 1
                wait = _retry_after_seconds(headers, body)
                if wait is None:
                    raise Abort("429 on /token with no recognisable wait time")
                self._wait(wait)
                continue
            if status >= 500:
                self.stats["5xx"] += 1
                transient += 1
                if transient > MAX_TRANSIENT_RETRIES:
                    raise Abort("token endpoint keeps failing")
                time.sleep(min(2 ** transient, 30))
                continue
            raise Abort("unexpected status %s from /token" % status)

    def _wait(self, seconds):
        total = seconds + WAIT_MARGIN
        log("service asked us to wait %.2fs -> sleeping %.2fs" % (seconds, total))
        self.stats["waited_s"] += total
        time.sleep(total)

    # -- authenticated GET --------------------------------------------------
    def get(self, path):
        """GET an authenticated JSON path. Returns (parsed_json, raw_text). Raises NotFound on 404."""
        transient = 0
        auth_failures_in_a_row = 0
        while True:
            if self.token is None:
                self.refresh_token()
            self.stats["requests"] += 1
            try:
                status, headers, body = _send("GET", path, self.token)
            except Exception as exc:
                self.stats["net_err"] += 1
                transient += 1
                log("GET %s network error: %r (attempt %d)" % (path, exc, transient))
                if transient > MAX_TRANSIENT_RETRIES:
                    raise Abort("gave up on %s after repeated network errors" % path)
                time.sleep(min(2 ** transient, 30))
                continue

            if status == 200:
                try:
                    parsed = json.loads(body)
                except Exception:
                    self.stats["bad_body"] += 1
                    transient += 1
                    log("GET %s -> 200 but body is not JSON: %r (attempt %d)" % (path, body[:300], transient))
                    if transient > MAX_TRANSIENT_RETRIES:
                        raise Abort("gave up on %s: body never parsed" % path)
                    time.sleep(min(2 ** transient, 30))
                    continue
                self.stats["ok"] += 1
                return parsed, body

            log("GET %s -> %s headers=%s body=%r" % (path, status, headers, body[:500]))
