                continue
            if status == 429:
                self.stats["429"] += 1
                wait = _retry_after_seconds(headers, body)
                if wait is None:
                    raise Abort("429 on %s with no recognisable wait time" % path)
                self._wait(wait)
                continue
            if status == 404:
                self.stats["404"] += 1
                raise NotFound(path)
            if status >= 500:
                self.stats["5xx"] += 1
                transient += 1
                if transient > MAX_TRANSIENT_RETRIES:
                    raise Abort("gave up on %s after repeated %s" % (path, status))
                wait = _retry_after_seconds(headers, body)
                self._wait(wait) if wait is not None else time.sleep(min(2 ** transient, 30))
