#!/usr/bin/env python3
"""Fetch every page of /orders by following `next`, caching each raw page under PAGES_DIR.

usage: fetch_orders.py PAGES_DIR
Resumable: pages already cached (and valid) are re-used without a request.
"""
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from client import Client, Abort, log  # noqa: E402

ORDER_KEYS = {"id", "customer_id", "status", "placed_at", "amount_cents"}


def validate(data, expected_page, expected_total):
    problems = []
    if not isinstance(data, dict):
        return ["page is not an object"]
    for k in ("page", "total_pages", "items", "next"):
        if k not in data:
            problems.append("missing key %r" % k)
    if problems:
        return problems
    if data["page"] != expected_page:
        problems.append("page=%r, expected %r" % (data["page"], expected_page))
    tp = data["total_pages"]
    if not isinstance(tp, int) or isinstance(tp, bool) or tp < 1:
        problems.append("bad total_pages %r" % (tp,))
    elif expected_total is not None and tp != expected_total:
        problems.append("total_pages changed: %r vs %r" % (tp, expected_total))
    if not isinstance(data["items"], list):
        problems.append("items is not a list")
    else:
        for i, it in enumerate(data["items"]):
            if not isinstance(it, dict) or set(it) != ORDER_KEYS:
                problems.append("item %d has unexpected shape: %r" % (i, it))
    if isinstance(tp, int):
        last = expected_page == tp
        if last and data["next"] is not None:
            problems.append("last page but next=%r" % (data["next"],))
        if not last and data["next"] != "/orders?page=%d" % (expected_page + 1):
            problems.append("next=%r, expected /orders?page=%d" % (data["next"], expected_page + 1))
    return problems


def main(pages_dir):
    os.makedirs(pages_dir, exist_ok=True)
    client = Client()
    n = 1
    total_pages = None
    while True:
        cache = os.path.join(pages_dir, "page-%03d.json" % n)
        if os.path.exists(cache):
            with open(cache) as fh:
                raw = fh.read()
            data = json.loads(raw)
            source = "cache"
        else:
            data, raw = client.get("/orders?page=%d" % n)
            source = "net"
        problems = validate(data, n, total_pages)
        if problems:
            log("page %d INVALID (%s): %s" % (n, source, "; ".join(problems)))
            log("raw (first 600 chars): %r" % raw[:600])
            raise Abort("page %d failed validation" % n)
        if source == "net":
            with open(cache, "w") as fh:
                fh.write(raw)
        total_pages = data["total_pages"]
        log("page %d/%d ok (%s): %d items, next=%r" % (n, total_pages, source, len(data["items"]), data["next"]))
        if data["next"] is None:
            break
        n += 1
    log("DONE fetching orders. stats=%s" % json.dumps(client.stats))


if __name__ == "__main__":
    main(sys.argv[1])

