#!/usr/bin/env python3
"""Fetch each needed customer exactly once (cached on disk), validating the record.

usage: fetch_customers.py QUALIFYING_JSON CUSTOMERS_DIR
Resumable: customers already cached are not requested again.
"""
import json
import os
import sys
import time

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from client import Client, NotFound, log  # noqa: E402

KEYS = {"id", "name", "region", "tier", "discount_pct"}
REGIONS = {"north", "south", "east", "west"}


def problems_with(cid, rec):
    p = []
    if not isinstance(rec, dict) or set(rec) != KEYS:
        return ["unexpected shape: %r" % (rec,)]
    if rec["id"] != cid:
        p.append("id mismatch: asked %r got %r" % (cid, rec["id"]))
    if rec["region"] not in REGIONS:
        p.append("region %r not one of %s" % (rec["region"], sorted(REGIONS)))
    d = rec["discount_pct"]
    if not isinstance(d, int) or isinstance(d, bool):
        p.append("discount_pct not an integer: %r" % (d,))
    elif not 0 <= d <= 100:
        p.append("discount_pct out of 0..100: %r" % (d,))
    return p


def main(qualifying_json, cust_dir):
    os.makedirs(cust_dir, exist_ok=True)
    needed = json.load(open(qualifying_json))["customers_needed"]
    client = Client()
    anomalies = {}
    missing = []
    for cid in needed:
        cache = os.path.join(cust_dir, cid + ".json")
        if os.path.exists(cache):
            rec = json.load(open(cache))
        else:
            rec = None
            for attempt in range(1, 4):          # a 404 is only believed after being repeated
                try:
                    rec, raw = client.get("/customers/" + cid)
                    break
                except NotFound:
                    log("%s -> 404 (attempt %d/3)" % (cid, attempt))
                    time.sleep(1.0)
            if rec is None:
                missing.append(cid)
                continue
            with open(cache, "w") as fh:
                fh.write(raw)
        probs = problems_with(cid, rec)
        if probs:
            anomalies[cid] = probs
            log("%s ANOMALY: %s" % (cid, "; ".join(probs)))
    log("customers: needed=%d cached_now=%d missing(404 x3)=%s anomalies=%d" % (
        len(needed), len(os.listdir(cust_dir)), missing, len(anomalies)))
    log("DONE fetching customers. stats=%s" % json.dumps(client.stats))
    if missing or anomalies:
        sys.exit(2)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

